/**
 * Authorized engagement orchestrator — create ROE record, chain Pentest Agent on every in-scope URL.
 */
import { supabase } from "@/integrations/supabase/client";
import { currentUserEmail } from "@/lib/auth-adapter";
import { runPentestScan } from "@/lib/redteam/pentest-client";
import type { PentestDepth, PentestFinding, PentestReport } from "@/lib/redteam/pentest-types";
import { generateId } from "@/lib/utils";

export type EngagementOrchestratorProgress = {
  phase: "authorizing" | "scanning" | "aggregating" | "done" | "error";
  currentUrl?: string;
  completed: number;
  total: number;
  message?: string;
};

export type AuthorizedEngagementInput = {
  clientName: string;
  scopeText: string;
  outOfScope?: string;
  depth: PentestDepth;
  /** Explicit URLs; if empty, parsed from scopeText */
  scopeUrls?: string[];
};

export type AuthorizedEngagementResult = {
  authorizationId: string;
  engagementId: string;
  reports: PentestReport[];
  aggregatedFindings: PentestFinding[];
  executiveSummary: string;
  grade: PentestReport["grade"];
  riskScore: number;
};

const DOMAIN_RE = /(?:^|\s)((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,})(?:\s|$|\/)/gi;
const URL_RE = /https?:\/\/[^\s<>"']+/gi;

/** Parse scope textarea into unique normalized https URLs. */
export function parseScopeToUrls(scopeText: string, explicit?: string[]): string[] {
  const set = new Set<string>();
  for (const u of explicit ?? []) {
    const t = u.trim();
    if (t) set.add(normalizeTargetUrl(t));
  }
  for (const m of scopeText.matchAll(URL_RE)) {
    try {
      set.add(normalizeTargetUrl(m[0]));
    } catch { /* skip */ }
  }
  const text = scopeText.replace(URL_RE, " ");
  for (const m of text.matchAll(DOMAIN_RE)) {
    const host = m[1].toLowerCase();
    if (!host.includes("localhost") && host.includes(".")) {
      set.add(`https://${host}/`);
    }
  }
  return [...set].slice(0, 25);
}

function normalizeTargetUrl(raw: string): string {
  const withProto = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
  const u = new URL(withProto);
  return u.origin + u.pathname.replace(/\/$/, "") + (u.pathname.endsWith("/") || u.pathname === "" ? "/" : "");
}

function portalFinding(f: PentestFinding, engagementId: string) {
  return {
    id: f.id,
    engagementId,
    title: f.title,
    severity: f.severity === "info" ? "informational" : f.severity,
    status: "open",
    affectedSystem: f.affectedAsset || "—",
    description: f.description,
    evidence: f.evidence,
    recommendation: f.recommendation,
    mitreTactic: f.mitreTactic ?? "",
    mitreTechnique: f.mitreTechnique ?? "",
    discoveredAt: new Date().toISOString(),
    remediatedAt: null,
    verifiedBy: null,
  };
}

function aggregateGrade(reports: PentestReport[]): { grade: PentestReport["grade"]; riskScore: number } {
  if (!reports.length) return { grade: "A", riskScore: 100 };
  const worst = Math.min(...reports.map((r) => r.riskScore));
  const grade =
    worst >= 90 ? "A" : worst >= 75 ? "B" : worst >= 60 ? "C" : worst >= 40 ? "D" : "F";
  return { grade, riskScore: Math.round(reports.reduce((s, r) => s + r.riskScore, 0) / reports.length) };
}

export async function runAuthorizedEngagement(
  input: AuthorizedEngagementInput,
  onProgress?: (p: EngagementOrchestratorProgress) => void,
): Promise<AuthorizedEngagementResult> {
  const email = currentUserEmail() ?? "operator@threatlens.local";
  const scopeUrls = parseScopeToUrls(input.scopeText, input.scopeUrls);
  if (!scopeUrls.length) {
    throw new Error("Add at least one in-scope URL or domain (e.g. https://example.com or example.com).");
  }

  onProgress?.({ phase: "authorizing", completed: 0, total: scopeUrls.length, message: "Recording authorization…" });

  const engagementId = generateId();
  const authorizationId = generateId();
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

  const engagementRow = {
    id: engagementId,
    name: `Authorized Pentest — ${input.clientName || scopeUrls[0]}`,
    type: "External Pentest",
    status: "active",
    client: input.clientName,
    scope: input.scopeText,
    objectives: "Automated authorized vulnerability assessment across in-scope assets",
    findings: [] as unknown[],
    exec_summary: "",
    target: scopeUrls[0],
    methodology: "PTES / OWASP WSTG automated phases",
    scope_urls: scopeUrls,
    authorization_id: authorizationId,
    authorized_by: email,
    start_date: new Date().toISOString().slice(0, 10),
  };

  const { error: engErr } = await supabase.from("redteam_engagements" as "threat_items").insert(engagementRow as never);
  if (engErr) throw new Error(`Could not create engagement: ${engErr.message}`);

  await supabase.from("redteam_authorizations" as "threat_items").insert({
    id: authorizationId,
    user_email: email,
    client_name: input.clientName,
    scope_text: input.scopeText,
    scope_urls: scopeUrls,
    out_of_scope: input.outOfScope ?? "",
    expires_at: expiresAt,
    status: "active",
    engagement_id: engagementId,
  });

  const reports: PentestReport[] = [];
  let completed = 0;

  for (const url of scopeUrls) {
    onProgress?.({
      phase: "scanning",
      currentUrl: url,
      completed,
      total: scopeUrls.length,
      message: `Scanning ${url}`,
    });
    const { report } = await runPentestScan({
      url,
      depth: input.depth,
      authorized: true,
      saveEngagement: false,
      clientName: input.clientName,
      engagementId,
    });
    reports.push(report);
    completed++;
  }

  onProgress?.({ phase: "aggregating", completed, total: scopeUrls.length, message: "Building engagement report…" });

  const aggregatedFindings = reports.flatMap((r) => r.findings);
  const { grade, riskScore } = aggregateGrade(reports);
  const executiveSummary =
    reports.length === 1
      ? reports[0].executiveSummary
      : `Authorized assessment of ${scopeUrls.length} in-scope asset(s) for ${input.clientName}. `
        + `Aggregate grade ${grade} (${riskScore}/100). `
        + `${aggregatedFindings.filter((f) => f.severity === "critical").length} critical and `
        + `${aggregatedFindings.filter((f) => f.severity === "high").length} high findings across targets. `
        + `Prioritize remediation on exposed secrets, CORS, and missing security headers.`;

  const portalFindings = aggregatedFindings.map((f) => portalFinding(f, engagementId));
  const aggregateReport = {
    engagementId,
    authorizationId,
    scannedAt: new Date().toISOString(),
    scopeUrls,
    reports,
    grade,
    riskScore,
    executiveSummary,
    findingCount: aggregatedFindings.length,
  };

  await supabase
    .from("redteam_engagements" as "threat_items")
    .update({
      status: "reporting",
      findings: portalFindings,
      exec_summary: executiveSummary,
      report: aggregateReport,
      updated_at: new Date().toISOString(),
    } as never)
    .eq("id", engagementId);

  onProgress?.({ phase: "done", completed: scopeUrls.length, total: scopeUrls.length });

  return {
    authorizationId,
    engagementId,
    reports,
    aggregatedFindings,
    executiveSummary,
    grade,
    riskScore,
  };
}
